"""
Tool Execution Abstraction for Localized Changes

This module centralizes dynamic tool loading, instantiation, execution,
and standardized error handling, replacing duplicated logic in ce3.py.
"""

import importlib
import inspect
import sys
from typing import Any, Dict, Union, Optional

from .base import BaseTool


class ToolResult:
    """Standardized result structure for tool execution."""

    def __init__(
        self,
        success: bool,
        data: Any = None,
        error: Optional[str] = None
    ):
        self.success = success
        self.data = data
        self.error = error

    @property
    def is_success(self) -> bool:
        return self.success

    @property
    def is_error(self) -> bool:
        return not self.success

    def to_dict(self) -> Dict[str, Any]:
        """Convert to dictionary representation."""
        if self.success:
            return {"success": True, "data": self.data}
        return {"success": False, "error": self.error}

    def __str__(self) -> str:
        if self.success:
            return str(self.data)
        return self.error or "Unknown error"


class ToolExecutor:
    """Encapsulates dynamic tool loading, instantiation, and execution."""

    def __init__(self):
        self._cached_modules: Dict[str, Any] = {}

    def execute(self, tool_name: str, tool_input: Dict[str, Any]) -> ToolResult:
        """
        Dynamically import, instantiate, and execute the specified tool.

        Args:
            tool_name: The tool's module/class name (e.g., 'filecreatortool')
            tool_input: Input parameters for the tool's execute method

        Returns:
            ToolResult with standardized success/error data
        """
        try:
            # Import module (cached for performance)
            module = self._import_tool_module(tool_name)
            if module is None:
                return ToolResult(
                    success=False,
                    error=f"Failed to import tool module: tools.{tool_name}"
                )

            # Find and instantiate the tool class
            tool_instance = self._find_tool_instance_in_module(module, tool_name)
            if tool_instance is None:
                return ToolResult(
                    success=False,
                    error=f"Tool class not found in module: tools.{tool_name}"
                )

            # Execute the tool
            result = tool_instance.execute(**tool_input)
            return ToolResult(success=True, data=result)

        except ImportError as e:
            return ToolResult(
                success=False,
                error=f"Failed to import tool '{tool_name}': {str(e)}"
            )
        except Exception as e:
            return ToolResult(
                success=False,
                error=f"Error executing tool '{tool_name}': {str(e)}"
            )

    def _import_tool_module(self, tool_name: str) -> Optional[Any]:
        """
        Import a tool module by name, using a cache for repeated lookups.

        Args:
            tool_name: Tool name (e.g., 'filecreatortool')

        Returns:
            The imported module, or None if import fails
        """
        module_path = f"tools.{tool_name}"

        # Use cached module if available
        if module_path in self._cached_modules:
            return self._cached_modules[module_path]

        try:
            module = importlib.import_module(module_path)
            self._cached_modules[module_path] = module
            return module
        except ImportError:
            return None

    def _find_tool_instance_in_module(
        self, module: Any, tool_name: str
    ) -> Optional[BaseTool]:
        """
        Find and instantiate the tool class matching tool_name in the module.

        Args:
            module: The imported module
            tool_name: The expected tool name

        Returns:
            An instance of the matching tool, or None if not found
        """
        for name, obj in inspect.getmembers(module):
            if (inspect.isclass(obj) and 
                issubclass(obj, BaseTool) and 
                obj != BaseTool):
                try:
                    tool_instance = obj()
                    if tool_instance.name == tool_name:
                        return tool_instance
                except Exception:
                    # Skip tools that fail to instantiate
                    continue
        return None


# Module-level singleton for convenient reuse
_executor: Optional[ToolExecutor] = None


def get_executor() -> ToolExecutor:
    """Get or create the global ToolExecutor instance."""
    global _executor
    if _executor is None:
        _executor = ToolExecutor()
    return _executor


def clear_executor_cache() -> None:
    """Clear the executor's module cache, forcing fresh imports."""
    global _executor
    if _executor is not None:
        _executor._cached_modules.clear()
        # Also clear sys.modules for tools to ensure fresh imports
        for key in list(sys.modules.keys()):
            if key.startswith('tools.') and key != 'tools.base':
                del sys.modules[key]
